for code in ['EM-700','EM-310','EM-400']:
 products.append(p('Nitto ELEP MOUNT '+code,'Die attachment film series integrated with dicing tape; exact thickness and precut configuration grouped.',c,'commercial',typ='product',sector='semiconductors',sub='materials_and_packaging',roles=['commercial_partner']))
for code,desc,source in [('PW-3610A','Acrylic adhesive on polyimide backing for heat-resistant semiconductor packaging masking.',d),('TRM-6250L','Silicone adhesive on polyimide backing for heat-resistant semiconductor packaging masking.',d),('FS-A101','Silver-particle sintering film for semiconductor bonding.',e)]:
 products.append(p('Nitto '+code,desc,source,'commercial',typ='product',sector='semiconductors',sub='materials_and_packaging',roles=['commercial_partner']))
products += [p('Nitto NEL MR3000III','Automatic 300 mm wafer remounter combining frame removal and MA3000III mounting functions.',f,'commercial',typ='product',sector='semiconductors',sub='semiconductor_equipment',roles=['commercial_partner'],aliases=['MR3000III']),p('ND-L02-s0201','HSP47 siRNA formulation studied for liver and pulmonary fibrosis. IPF efficacy endpoint unmet and NASH trial stopped; current overall continuation unverified.',g,'unknown',aliases=['BMS-986263']),p('NBF-006','Lipid nanoparticle GST-pi siRNA formulation historically developed for KRAS-driven cancers; current clinical status unverified.',h,'unknown'),p('NittoPhase HL','High-loading polymer solid support family for DNA and RNA oligonucleotide synthesis; loading and linker variants require catalogue reconciliation.',i,'commercial',typ='product',sub='research_tools',roles=['commercial_partner']),p('NittoPhase SL','Announced higher-functional-density solid support for short-mer oligonucleotide synthesis; actual launch after planned Q3 2026 unverified.',i,'unknown',typ='product',sub='research_tools',roles=['commercial_partner']),p('Nitto BioPharma nucleic-acid delivery platform','Lipid and polymer carrier technology for delivery of oligonucleotide and other genetic medicine cargos.',j,'commercial',typ='technology',sub='research_tools',roles=['commercial_partner']),p('Nitto NITOFLON No.903UL','PTFE film adhesive tape with secondary-battery electrode insulation application; thickness options grouped.',k,'commercial',typ='product',sector='energy_storage',sub='batteries',roles=['commercial_partner'])]
co=company('Nitto Denko Corporation',products,[a,b,c,d,e,f,g,h,i,j,k],'Initial semiconductor grade catalogue, one equipment model, battery insulation material and named nucleic-acid products reviewed. NT resin grades represented individually; series families not duplicated. Partial: remaining ELEP tapes, NEL coded equipment, EM-500 US regional entry, battery materials, transdermal medicines and historical platforms, current drug status and solid-support linker/loading variants remain. Duplicate company records need shared product IDs, not duplicate product identities.',status='partial')
(out/'batch-0191.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
